ALTER TABLE "Order" ADD COLUMN "tip" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Order" ADD COLUMN "courierRating" INTEGER;
ALTER TABLE "Order" ADD COLUMN "courierRatedAt" TIMESTAMP(3);
CREATE TABLE "OrderMessage" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrderMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OrderMessage_orderId_createdAt_idx" ON "OrderMessage"("orderId","createdAt");
ALTER TABLE "OrderMessage" ADD CONSTRAINT "OrderMessage_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "ShopSettings" ("id" TEXT NOT NULL DEFAULT 'main', "fuelPerKm" DOUBLE PRECISION NOT NULL DEFAULT 8, "averageKm" DOUBLE PRECISION NOT NULL DEFAULT 4, "bagCost" DOUBLE PRECISION NOT NULL DEFAULT 12, "packingCost" DOUBLE PRECISION NOT NULL DEFAULT 8, "paymentPercent" DOUBLE PRECISION NOT NULL DEFAULT 2.5, "otherOrderCost" DOUBLE PRECISION NOT NULL DEFAULT 0, "baseDeliveryFee" INTEGER NOT NULL DEFAULT 199, "weatherSurcharge" INTEGER NOT NULL DEFAULT 50, "demandSurcharge" INTEGER NOT NULL DEFAULT 50, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ShopSettings_pkey" PRIMARY KEY ("id"));
INSERT INTO "ShopSettings"("id","updatedAt") VALUES ('main',CURRENT_TIMESTAMP);
